package com.finstack.alert;
import com.finstack.alert.dto.AlertResponse; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/alerts") public class AlertController {private final AlertService service;public AlertController(AlertService s){service=s;}@GetMapping public Page<AlertResponse> list(@RequestParam(required=false)Boolean read,@RequestParam(required=false)AlertType type,@RequestParam(required=false)AlertSeverity severity,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p){return service.list(read,type,severity,p);}@PatchMapping("/{id}/read") public ResponseEntity<Void> read(@PathVariable UUID id){service.markRead(id);return ResponseEntity.noContent().build();}@PatchMapping("/read-all") public ResponseEntity<Void> readAll(){service.markAllRead();return ResponseEntity.noContent().build();}}
